#include <barrier>
#include <thread>
#include <cassert>
#include <type_traits>
#include <utility>

int main() {
    std::barrier barrier{2};
    assert(decltype(barrier)::max() >= 2);
    std::jthread worker([&] { barrier.arrive_and_wait(); });
    auto token = barrier.arrive();
    barrier.wait(std::move(token));
    worker.join();
    barrier.arrive_and_drop();
    barrier.arrive_and_wait();
}
